//! The CPython 3.12 truth tables of `tests/vectors/` (01 Addendum §A.8, generated by `cargo xtask pyre-vectors`):
//! acceptance (ok / exception class, message, position, `str(e)`, `FutureWarning`s) and match results
//! (`re.search` / `re.match` / `re.fullmatch`, spans for bytes patterns) for the edge list, the corpus, the
//! grammar fuzz sets and the nesting rows.
//!
//! The only tolerated differences are 01 Addendum §A.6.13 D1 (IGNORECASE back-references) and the D7 error class
//! of `\U` escapes above 0x7FFFFFFF (`OverflowError` in CPython, a `bad escape` in snp), both in D-MISC-06.
//!
//! Owner: WP-13.

#[cfg(test)]
#[expect(
    clippy::disallowed_methods,
    reason = "test inputs built with fixed, non-zero repeat counts and steps"
)]
mod vectors {
    use std::path::PathBuf;
    use std::sync::OnceLock;

    use serde_json::Value;
    use snp_pyre::{Haystack, Mode, Options, PyReError, PyRegex};

    /// The committed vectors, or (for exploratory runs of other generator seeds) the directory named by
    /// `SNP_PYRE_VECTORS_DIR` at build time.
    fn vectors_dir() -> PathBuf {
        option_env!("SNP_PYRE_VECTORS_DIR").map_or_else(
            || PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/vectors"),
            PathBuf::from,
        )
    }

    fn load(name: &str) -> Value {
        let path = vectors_dir().join(name);
        let text =
            std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
        serde_json::from_str(&text).unwrap()
    }

    struct Haystacks {
        fuzz_str: Vec<String>,
        paths: Vec<String>,
        fuzz_bytes: Vec<Vec<u8>>,
        lines: Vec<Vec<u8>>,
    }

    fn unhex(s: &str) -> Vec<u8> {
        (0..s.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(s.get(i..i + 2).unwrap(), 16).unwrap())
            .collect()
    }

    fn haystacks() -> &'static Haystacks {
        static H: OnceLock<Haystacks> = OnceLock::new();
        H.get_or_init(|| {
            let v = load("haystacks.json");
            let strs = |k: &str| {
                v[k].as_array()
                    .unwrap()
                    .iter()
                    .map(|x| x.as_str().unwrap().to_owned())
                    .collect()
            };
            let bytes = |k: &str| {
                v[k].as_array()
                    .unwrap()
                    .iter()
                    .map(|x| unhex(x.as_str().unwrap()))
                    .collect()
            };
            Haystacks {
                fuzz_str: strs("fuzz_str"),
                paths: strs("paths"),
                fuzz_bytes: bytes("fuzz_bytes"),
                lines: bytes("lines"),
            }
        })
    }

    /// FNV-1a-64 over 32-bit little-endian integers (the generator's `fnv`).
    fn fnv(values: &[u64]) -> String {
        let mut h: u64 = 0xCBF2_9CE4_8422_2325;
        for v in values {
            for b in u32::try_from(*v).unwrap().to_le_bytes() {
                h ^= u64::from(b);
                h = h.wrapping_mul(0x100_0000_01B3);
            }
        }
        format!("{h:016x}")
    }

    fn pair(v: &Value) -> (u64, String) {
        (v[0].as_u64().unwrap(), v[1].as_str().unwrap().to_owned())
    }

    fn options(row: &Value, haystack: Haystack) -> Options {
        let mode = if row["md"] == "s" {
            Mode::Str
        } else {
            Mode::Bytes
        };
        let fl = row["fl"].as_str().unwrap_or("");
        Options {
            mode,
            haystack,
            ignore_case: fl.contains('i'),
            multiline_dotall: fl.contains('m'),
        }
    }

    /// D1 (01 Addendum §A.6.13): a back-reference under IGNORECASE may legitimately disagree.
    fn ci_backref(row: &Value) -> bool {
        static RE: OnceLock<regex::Regex> = OnceLock::new();
        let p = row["p"].as_str().unwrap();
        let ci = row["fl"].as_str().unwrap_or("").contains('i')
            || RE
                .get_or_init(|| regex::Regex::new(r"\(\?[aiLmsux]*i[aiLmsux-]*[:)]").unwrap())
                .is_match(p);
        let backref = p.contains("(?P=")
            || p.as_bytes()
                .windows(2)
                .any(|w| w[0] == b'\\' && (b'1'..=b'9').contains(&w[1]));
        ci && backref
    }

    fn describe_err(e: &PyReError) -> String {
        format!("{e:?} / {e}")
    }

    /// D5/D6 (01 Addendum §A.6.13): a repeat count large enough to exceed the engines' 64 MiB size limit, or a
    /// backtracking pattern nested past fancy-regex's 63 levels, is `Unsupported` although CPython compiles it.
    fn d5_or_d6(p: &str) -> bool {
        static RE: OnceLock<regex::Regex> = OnceLock::new();
        let big = RE
            .get_or_init(|| regex::Regex::new(r"\{,?[0-9]{6,}").unwrap())
            .is_match(p);
        let mut depth = 0_u32;
        let mut max = 0_u32;
        for c in p.chars() {
            match c {
                '(' => {
                    depth += 1;
                    max = max.max(depth);
                }
                ')' => depth = depth.saturating_sub(1),
                _ => {}
            }
        }
        big || max >= 30
    }

    /// Checks acceptance; returns the compiled pattern when both sides accept.
    #[expect(
        clippy::unwrap_in_result,
        reason = "a malformed vector row aborts the test"
    )]
    fn check_accept(row: &Value, opts: Options, out: &mut Vec<String>) -> Option<PyRegex> {
        let p = row["p"].as_str().unwrap();
        let got = PyRegex::compile(p, opts);
        let validated = snp_pyre::validate(p, opts.mode);
        if validated.is_ok() != got.is_ok() && !matches!(got, Err(PyReError::Unsupported(_))) {
            out.push(format!(
                "{p:?} {opts:?}: validate {validated:?} vs compile {:?}",
                got.as_ref().err()
            ));
        }
        let expected_warnings: Vec<String> = row["w"]
            .as_array()
            .map(|a| a.iter().map(|x| x.as_str().unwrap().to_owned()).collect())
            .unwrap_or_default();
        if row["ok"] == true {
            match got {
                Ok(re) => {
                    let w: Vec<String> = re.warnings().iter().map(|w| w.msg.to_string()).collect();
                    if w != expected_warnings {
                        out.push(format!(
                            "{p:?} {opts:?}: warnings {w:?}, expected {expected_warnings:?}"
                        ));
                    }
                    if let Ok(vw) = &validated {
                        let vw: Vec<String> = vw.iter().map(|w| w.msg.to_string()).collect();
                        if vw != expected_warnings {
                            out.push(format!(
                                "{p:?}: validate warnings {vw:?}, expected {expected_warnings:?}"
                            ));
                        }
                    }
                    return Some(re);
                }
                Err(PyReError::Unsupported(_)) if d5_or_d6(p) && validated.is_ok() => return None,
                Err(e) => {
                    out.push(format!(
                        "{p:?} {opts:?}: CPython accepts, snp: {}",
                        describe_err(&e)
                    ));
                    return None;
                }
            }
        }
        let t = row["t"].as_str().unwrap();
        let want_str = row["str"].as_str().unwrap();
        let Err(e) = got else {
            out.push(format!(
                "{p:?} {opts:?}: CPython raises {t}: {want_str}, snp accepts"
            ));
            return None;
        };
        let ok = match (&e, t) {
            (PyReError::Re { pos, .. }, "re.error") => {
                let want_pos = row["pos"].as_u64().map(|x| usize::try_from(x).unwrap());
                *pos == want_pos && e.to_string() == want_str
            }
            (PyReError::Overflow, "OverflowError") | (PyReError::Recursion, "RecursionError") => {
                true
            }
            (PyReError::Value(m), "ValueError") => **m == *want_str,
            // D7 (D-MISC-06): `\U` above 0x7FFFFFFF in a str pattern, where CPython's `chr` raises
            // `OverflowError: Python int too large to convert to C int`; snp reports the `bad escape`.
            (PyReError::Re { msg, .. }, "OverflowError")
                if want_str == "Python int too large to convert to C int"
                    && msg.starts_with("bad escape \\U") =>
            {
                true
            }
            _ => false,
        };
        if !ok {
            out.push(format!(
                "{p:?} {opts:?}: CPython {t}: {want_str:?} (pos {}), snp {}",
                row["pos"],
                describe_err(&e)
            ));
        }
        None
    }

    fn check_str_matches(row: &Value, re: &PyRegex, out: &mut Vec<String>) {
        let p = row["p"].as_str().unwrap();
        let set = match row["set"].as_str() {
            Some("fuzz_str") => &haystacks().fuzz_str,
            Some("paths") => &haystacks().paths,
            _ => return,
        };
        let mut hits: [Vec<u64>; 3] = [Vec::new(), Vec::new(), Vec::new()];
        for (i, h) in set.iter().enumerate() {
            let i = u64::try_from(i).unwrap();
            let r = [re.search(h), re.match_prefix(h), re.fullmatch(h)];
            for (k, res) in r.iter().enumerate() {
                match res {
                    Ok(true) => hits[k].push(i),
                    Ok(false) => {}
                    Err(e) => out.push(format!("{p:?} on {h:?}: {e:?}")),
                }
            }
        }
        for (k, key) in ["s", "m", "f"].iter().enumerate() {
            let (count, hash) = pair(&row[*key]);
            let got = (u64::try_from(hits[k].len()).unwrap(), fnv(&hits[k]));
            if got != (count, hash.clone()) {
                out.push(format!(
                    "{p:?} [{key}] over {}: count {} vs CPython {count} (kind {:?})",
                    row["set"],
                    got.0,
                    re.kind()
                ));
            }
        }
        for own in row["own"].as_array().into_iter().flatten() {
            let h = own[0].as_str().unwrap();
            let want = [
                own[1].as_bool().unwrap(),
                own[2].as_bool().unwrap(),
                own[3].as_bool().unwrap(),
            ];
            let got = [re.search(h), re.match_prefix(h), re.fullmatch(h)];
            for k in 0..3 {
                if got[k] != Ok(want[k]) {
                    out.push(format!(
                        "{p:?} [{}] on own {h:?}: snp {:?}, CPython {}",
                        ["s", "m", "f"][k],
                        got[k],
                        want[k]
                    ));
                }
            }
        }
    }

    fn line_shaped(h: &[u8]) -> bool {
        !h[..h.len().saturating_sub(1)].contains(&b'\n')
    }

    fn span_of(v: &Value) -> Option<(usize, usize)> {
        v.as_array().map(|a| {
            (
                usize::try_from(a[0].as_u64().unwrap()).unwrap(),
                usize::try_from(a[1].as_u64().unwrap()).unwrap(),
            )
        })
    }

    fn check_bytes_matches(
        row: &Value,
        blob: &PyRegex,
        line: Option<&PyRegex>,
        out: &mut Vec<String>,
    ) -> bool {
        let p = row["p"].as_str().unwrap();
        let set = match row["set"].as_str() {
            Some("fuzz_bytes") => &haystacks().fuzz_bytes,
            Some("lines") => &haystacks().lines,
            _ => return false,
        };
        let mut spans = Vec::new();
        let mut line_spans = Vec::new();
        let mut m_hits = Vec::new();
        let mut f_hits = Vec::new();
        for (i, h) in set.iter().enumerate() {
            let i64v = u64::try_from(i).unwrap();
            match blob.search_bytes(h) {
                Ok(Some((s, e))) => {
                    spans.extend([i64v, u64::try_from(s).unwrap(), u64::try_from(e).unwrap()]);
                }
                Ok(None) => {}
                Err(e) => out.push(format!("{p:?} on {h:?}: {e:?}")),
            }
            if let Some(line) = line
                && line_shaped(h)
            {
                match line.search_bytes(h) {
                    Ok(Some((s, e))) => line_spans.extend([
                        i64v,
                        u64::try_from(s).unwrap(),
                        u64::try_from(e).unwrap(),
                    ]),
                    Ok(None) => {}
                    Err(e) => out.push(format!("{p:?} (line) on {h:?}: {e:?}")),
                }
            }
            if let Ok(t) = std::str::from_utf8(h) {
                if blob.match_prefix(t) == Ok(true) {
                    m_hits.push(i64v);
                }
                if blob.fullmatch(t) == Ok(true) {
                    f_hits.push(i64v);
                }
            }
        }
        // D8 (D-MISC-06): the nullable loops snp cannot run like CPython's `MAX_UNTIL` (bounded, possessive, or
        // `{2,}` with observable captures) may end a match at a different place (never decide whether there is
        // one): span-only differences of such rows are tolerated and counted (bounded by `assert_vectors`).
        let nullable_loop = row["nl"] == true;
        let mut tolerated = false;
        let checks: [(&str, &Vec<u64>, u64); 3] = [
            ("s", &spans, u64::try_from(spans.len() / 3).unwrap()),
            ("m", &m_hits, u64::try_from(m_hits.len()).unwrap()),
            ("f", &f_hits, u64::try_from(f_hits.len()).unwrap()),
        ];
        for (key, hits, count) in checks {
            let (want_count, want_hash) = pair(&row[key]);
            if (count, fnv(hits)) != (want_count, want_hash.clone()) {
                if nullable_loop && key == "s" && count == want_count {
                    tolerated = true;
                    continue;
                }
                out.push(format!("{p:?} fl={} [{key}] over {}: count {count} vs CPython {want_count} (kind {:?})", row["fl"], row["set"], blob.kind()));
            }
        }
        if line.is_some() && row["sl"].is_array() {
            let (want_count, want_hash) = pair(&row["sl"]);
            let count = u64::try_from(line_spans.len() / 3).unwrap();
            if (count, fnv(&line_spans)) != (want_count, want_hash) {
                if nullable_loop && count == want_count {
                    tolerated = true;
                } else {
                    out.push(format!("{p:?} fl={} [s, Haystack::Line] over {}: count {count} vs CPython {want_count}", row["fl"], row["set"]));
                }
            }
        }
        let same_start = |got: &Result<Option<(usize, usize)>, snp_pyre::MatchError>,
                          want: Option<(usize, usize)>| {
            matches!((got, want), (Ok(Some((a, _))), Some((b, _))) if *a == b)
        };
        for own in row["own"].as_array().into_iter().flatten() {
            let h = unhex(own[0].as_str().unwrap());
            let want = span_of(&own[1]);
            let got = blob.search_bytes(&h);
            if got != Ok(want) {
                if nullable_loop && same_start(&got, want) {
                    tolerated = true;
                } else {
                    out.push(format!(
                        "{p:?} fl={} on own {h:?}: snp {got:?}, CPython {want:?}",
                        row["fl"]
                    ));
                }
            }
            if let Some(line) = line
                && line_shaped(&h)
            {
                let got = line.search_bytes(&h);
                if got != Ok(want) {
                    if nullable_loop && same_start(&got, want) {
                        tolerated = true;
                    } else {
                        out.push(format!(
                            "{p:?} fl={} (line) on own {h:?}: snp {got:?}, CPython {want:?}",
                            row["fl"]
                        ));
                    }
                }
            }
            if let Ok(t) = std::str::from_utf8(&h) {
                for (k, idx) in [(blob.match_prefix(t), 2), (blob.fullmatch(t), 3)] {
                    if let Some(w) = own[idx].as_bool()
                        && k != Ok(w)
                    {
                        out.push(format!(
                            "{p:?} fl={} [{}] on own {h:?}: snp {k:?}, CPython {w}",
                            row["fl"],
                            if idx == 2 { "m" } else { "f" }
                        ));
                    }
                }
            }
        }
        tolerated
    }

    /// Rows whose differences were tolerated, per residual class (reported, and bounded by `assert_vectors`).
    #[derive(Default, Clone, Copy)]
    struct Tally {
        /// D1: IGNORECASE back-references.
        d1: usize,
        /// Span ends of a repeated nullable body (the regex crate's empty-iteration priority).
        spans: usize,
        /// A conditional re-entering its own group inside a repetition.
        conds: usize,
    }

    fn check_row(row: &Value, out: &mut Vec<String>, tally: &mut Tally) {
        let before = out.len();
        if row["md"] == "s" {
            if let Some(re) = check_accept(row, options(row, Haystack::Path), out) {
                check_str_matches(row, &re, out);
            }
        } else {
            let blob = check_accept(row, options(row, Haystack::Blob), out);
            let line =
                PyRegex::compile(row["p"].as_str().unwrap(), options(row, Haystack::Line)).ok();
            if let Some(blob) = blob
                && check_bytes_matches(row, &blob, line.as_ref(), out)
            {
                tally.spans += 1;
            }
        }
        let accept_ok = out[before..]
            .iter()
            .all(|m| !m.contains("CPython accepts") && !m.contains("warnings"));
        if out.len() > before && ci_backref(row) && row["ok"] == true && accept_ok {
            // D1: tolerated, but only for match differences.
            tally.d1 += 1;
            out.truncate(before);
        }
        if out.len() > before && row["cr"] == true && row["ok"] == true && accept_ok {
            // A conditional re-entering its own group in a repetition: tolerated, but only for match differences.
            tally.conds += 1;
            out.truncate(before);
        }
    }

    /// Runs `rows` on several threads; returns every mismatch and the tolerated rows.
    fn run_rows(rows: &[Value]) -> (Vec<String>, Tally) {
        let threads = std::thread::available_parallelism()
            .map_or(4, std::num::NonZero::get)
            .min(8);
        let chunk = rows.len().div_ceil(threads).max(1);
        std::thread::scope(|s| {
            let handles: Vec<_> = rows
                .chunks(chunk)
                .map(|part| {
                    std::thread::Builder::new()
                        .stack_size(8 << 20)
                        .spawn_scoped(s, move || {
                            let mut out = Vec::new();
                            let mut tally = Tally::default();
                            for row in part {
                                check_row(row, &mut out, &mut tally);
                            }
                            (out, tally)
                        })
                        .unwrap()
                })
                .collect();
            let mut failures = Vec::new();
            let mut total = Tally::default();
            for h in handles {
                let (out, t) = h.join().unwrap();
                failures.extend(out);
                total.d1 += t.d1;
                total.spans += t.spans;
                total.conds += t.conds;
            }
            (failures, total)
        })
    }

    fn assert_vectors(name: &str) {
        let v = load(name);
        let rows = v.as_array().unwrap();
        let (failures, Tally { d1, spans, conds }) = run_rows(rows);
        eprintln!(
            "{name}: {} rows; tolerated: {d1} D1 (IGNORECASE back-reference), {spans} span-end (nullable loop body), \
             {conds} conditional re-entry",
            rows.len()
        );
        assert!(
            d1 * 200 <= rows.len(),
            "{name}: {d1} D1 rows is more than the 0.5% the corpus run measured"
        );
        // The committed vectors meet CPython exactly outside D1 (WBS WP-13); the span-end and conditional
        // re-entry classes are only tolerated (and bounded) for exploratory runs of other generator seeds.
        let (span_cap, cond_cap) = if option_env!("SNP_PYRE_VECTORS_DIR").is_some() {
            (rows.len() / 1000, rows.len() / 1000)
        } else {
            (0, 0)
        };
        assert!(
            spans <= span_cap,
            "{name}: {spans} span-end rows (allowed: {span_cap})"
        );
        assert!(
            conds <= cond_cap,
            "{name}: {conds} conditional re-entry rows (allowed: {cond_cap})"
        );
        if !failures.is_empty() {
            let shown: Vec<&String> = failures.iter().take(60).collect();
            panic!(
                "{name}: {} mismatches of {} rows:\n{}",
                failures.len(),
                rows.len(),
                shown
                    .iter()
                    .map(|s| s.as_str())
                    .collect::<Vec<_>>()
                    .join("\n")
            );
        }
    }

    #[test]
    fn edge_list() {
        assert_vectors("edge.json");
    }

    #[test]
    fn corpus() {
        assert_vectors("corpus.json");
    }

    #[test]
    fn fuzz_str() {
        assert_vectors("fuzz_str.json");
    }

    #[test]
    fn fuzz_bytes() {
        assert_vectors("fuzz_bytes.json");
    }

    /// 484 nested groups compile, 485 raise `RecursionError` (and the conditional / look-around shapes at
    /// pre-commit's stack depth, 01 Addendum §A.4).
    #[test]
    fn nesting() {
        let v = load("nesting.json");
        let mut failures = Vec::new();
        for row in v["rows"].as_array().unwrap() {
            let shape = row["shape"].as_str().unwrap();
            let n = usize::try_from(row["n"].as_u64().unwrap()).unwrap();
            let p = match shape {
                "cap" => format!("{}a{}", "(".repeat(n), ")".repeat(n)),
                "noncap" => format!("{}a{}", "(?:".repeat(n), ")".repeat(n)),
                "look" => format!("{}a{}", "(?=".repeat(n), ")".repeat(n)),
                "behind" => format!("{}a{}", "(?<=".repeat(n), ")".repeat(n)),
                "atomic" => format!("{}a{}", "(?>".repeat(n), ")".repeat(n)),
                "flags" => format!("{}a{}", "(?i:".repeat(n), ")".repeat(n)),
                "capq" => format!("{}a{}", "(".repeat(n), ")*".repeat(n)),
                "branch" => format!("{}b{}", "(a|".repeat(n), ")".repeat(n)),
                "cond" => format!("(a){}a{}", "(?(1)".repeat(n), ")".repeat(n)),
                other => panic!("unknown shape {other}"),
            };
            let mode = if row["md"] == "s" {
                Mode::Str
            } else {
                Mode::Bytes
            };
            let validated = snp_pyre::validate(&p, mode);
            let want_ok = row["ok"] == true;
            if validated.is_ok() != want_ok {
                failures.push(format!(
                    "{shape} x{n} {mode:?}: validate {:?}, CPython ok={want_ok} {}",
                    validated.err(),
                    row["t"]
                ));
                continue;
            }
            if !want_ok {
                if validated != Err(PyReError::Recursion) {
                    failures.push(format!("{shape} x{n}: {:?}", validated.err()));
                }
                continue;
            }
            let opts = Options {
                mode,
                ..Options::CONFIG
            };
            match PyRegex::compile(&p, opts) {
                Ok(re) => {
                    let hays = ["a", "ab", "b", ""];
                    for (h, want) in hays.iter().zip(row["hit"].as_array().unwrap()) {
                        if re.search(h) != Ok(want.as_bool().unwrap()) {
                            failures.push(format!(
                                "{shape} x{n} {mode:?}: search {h:?} = {:?}",
                                re.search(h)
                            ));
                        }
                    }
                }
                // D6: deep tier-2 patterns exceed fancy-regex's nesting (01 Addendum §A.6.13).
                Err(PyReError::Unsupported(_))
                    if !matches!(shape, "cap" | "noncap" | "flags" | "capq" | "branch")
                        || n > 484 => {}
                Err(e) => failures.push(format!("{shape} x{n} {mode:?}: compile {e:?}")),
            }
        }
        assert!(failures.is_empty(), "{}", failures.join("\n"));
    }
}
